#!/bin/bash
# xsim test of the boot ROM VHDL template.  Usage: test/run_rom_xsim.sh [rom.vhd]
# Default: ../OSDBoot_rv_ROM.vhd (generated by `make`).  Vivado 2023.2.
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
ROM=${1:-$HERE/../OSDBoot_rv_ROM.vhd}
VIVADO_PATH=${VIVADO_PATH:-/opt/Xilinx/Vivado/2023.2}
export LC_ALL=C LANG=C
export LD_LIBRARY_PATH="$HOME/lib/tinfo5${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
OUT=$HERE/out/xsim
mkdir -p "$OUT"; cd "$OUT"
# the ROM compiles as plain VHDL-93; only the bench needs 2008 (to_hstring)
{ "$VIVADO_PATH/bin/xvhdl" "$ROM" && "$VIVADO_PATH/bin/xvhdl" --2008 "$HERE/rom_tb.vhd"; } > xvhdl.log 2>&1 || { tail -20 xvhdl.log; exit 1; }
"$VIVADO_PATH/bin/xelab" -debug off rom_tb -s rom_tb > xelab.log 2>&1 || { tail -20 xelab.log; exit 1; }
"$VIVADO_PATH/bin/xsim" rom_tb -runall > xsim.log 2>&1 || true
grep -E "ROM xsim test|Error|FAIL|got " xsim.log || true
grep -q "ROM xsim test: PASS" xsim.log && ! grep -q "Error" xsim.log
